sys_script_include.script:
var FleetLicenseUtils = Class.create();

/**
 * FLEET-16: true if the user has a driver license whose expiration_date is on or after the given date.
 * @param {string} userSysId - sys_user sys_id
 * @param {GlideDateTime|string} [gdt] - date to check (defaults to now)
 * @returns {boolean}
 */
FleetLicenseUtils.isValidOn = function(userSysId, gdt) {
    if (!userSysId) {
        return false;
    }
    var lic = new GlideRecord('x_1850693_enterp_0_driver_license');
    lic.addQuery('employee', userSysId);
    lic.setLimit(1);
    lic.query();
    if (!lic.next() || lic.expiration_date.nil()) {
        return false;
    }
    var when = gdt ? new GlideDateTime(gdt) : new GlideDateTime();
    return lic.getValue('expiration_date') >= when.getLocalDate().getValue();
};

FleetLicenseUtils.prototype = {
    initialize: function() {},
    type: 'FleetLicenseUtils'
};
